lemma barVal_add_right {k l : ℕ} (x : BarT I k) (q : Fin k) {y z w : BarT I l}
    (h : y.val = z.val + w.val) (m : ℕ) (hm : m + 1 = k + l) :
    barVal I x q y m hm = barVal I x q z m hm + barVal I x q w m hm

lemma path_ctx_of_not_mem (hnd : M.labels.Nodup) {y : LTree E}
    (hy : y.labels.Perm (List.range k)) {i : ℕ} (hi : i ∈ M.labels)
    (hi' : i ∉ (M.subtreeAt q).labels) : (M.replaceAt q (y.plug ins)).path i = M.path i

lemma isEdge_ctx_ins {y : LTree E} {j : ℕ} (hj : j ∈ y.labels) {d : List Bool} {s : Bool}
    (he : (ins j).IsEdge d s) :
    (M.replaceAt q (y.plug ins)).IsEdge (q ++ (leafPos j y ++ d)) s

lemma mk_add_y (g : GrCompGen M N S) (a : g.A) (z z' : N (g.B a)) :
    mk R { g with y := update g.y a (z + z') }
      = mk R { g with y := update g.y a z } + mk R { g with y := update g.y a z' }

lemma mk_reorder (g : GrCompGen M N S) (L' : LinOrd g.A) (c : g.A → Bool)
    (hy : ∀ a, GrSpecies.par (R := R) (c a) (g.y a) = g.y a) :
    mk R g = GrEnd.rsg R g.L L' c • mk R { g with L := L' }

lemma app_update (ψ : GrSpeciesHom R N N') {A : Type} [DecidableEq A] {B : A → Type}
    [∀ a, Fintype (B a)] [∀ a, DecidableEq (B a)] (y : ∀ a, N (B a)) (a : A) (z : N (B a)) :
    (fun a' => ψ.app _ (update y a z a')) = update (fun a' => ψ.app _ (y a')) a (ψ.app _ z)

lemma pr_apply_hom {c : A → Bool} {x : A → V} (hx : IsHom (R := R) c x) {q : Bool}
    {g : EndOp R V A} (hg : parML R V q g = g) :
    SuperMod.pr (R := R) (xor q (tot c)) (g x) = g x

lemma isHom_feed (i : A) {e : Without A i ⊕ B → Bool} {x : Without A i ⊕ B → V}
    (hx : IsHom (R := R) e x) {q : Bool} {g : EndOp R V B} (hg : parML R V q g = g) :
    IsHom (R := R) (slot i q e) (feed i x (g fun b => x (Sum.inr b)))

lemma kcomp_apply_hom (L : LinOrd A) (i : A) (f : EndOp R V A) {q : Bool} {g : EndOp R V B}
    (hg : parML R V q g = g) {e : Without A i ⊕ B → Bool} {x : Without A i ⊕ B → V}
    (hx : IsHom (R := R) e x) :
    kcomp R V L i f g x = bsg R L i q (slot i q e) • f (feed i x (g fun b => x (Sum.inr b)))

lemma mem_span_two {G : Type v} {r₂ : Set (FreeBin K G (Fin 2))} {r₃ : Set (FreeBin K G (Fin 3))}
    {x : FreeBin K G (Fin 2)} (hx : x ∈ r₂) (c : K) :
    c • x ∈ (SymOperadIdeal.span K (rel23 r₂ r₃)).sub (Fin 2)

lemma mem_span_three {G : Type v} {r₂ : Set (FreeBin K G (Fin 2))} {r₃ : Set (FreeBin K G (Fin 3))}
    {x : FreeBin K G (Fin 3)} (hx : x ∈ r₃) (c : K) :
    c • x ∈ (SymOperadIdeal.span K (rel23 r₂ r₃)).sub (Fin 3)

lemma InnerOp.par_app_hom {B : Type} [Fintype B] [DecidableEq B] {c : Bool} {x : C B}
    (hx : GrOperad.par (R := R) c x = x) :
    GrSpecies.par (R := R) (xor c e) (Φ.app B x) = Φ.app B x

theorem substBar_injective {y : BarTree E} (hy : Valid y) {p : List Bool} {s : Bool}
    (h : IsUncut y p s) {σ τ : Mono E 3} (he : substBar y p s σ.1 = substBar y p s τ.1) :
    σ = τ

theorem substBar_eq_substBar {x y : BarTree E} (hx : Valid x) (hy : Valid y)
    (hc : (cutKeys y).card + 3 = y.arity) {p p' : List Bool} {s s' : Bool}
    (hux : IsUncut x p' s') (huy : IsUncut y p s) {σ₀ τ₀ : Mono E 3}
    (h : substBar x p' s' τ₀.1 = substBar y p s σ₀.1) :
    p' = p ∧ ∀ τ : Mono E 3, substBar x p' s' τ.1 = substBar y p s τ.1

theorem substBar_eq_iff {x y : BarTree E} (hx : Valid x) (hy : Valid y)
    (hc : (cutKeys y).card + 3 = y.arity) {p p' : List Bool} {s s' : Bool}
    (hux : IsUncut x p' s') (huy : IsUncut y p s) {σ₀ τ₀ : Mono E 3}
    (h : substBar x p' s' τ₀.1 = substBar y p s σ₀.1) (σ τ : Mono E 3) :
    substBar x p' s' τ.1 = substBar y p s σ.1 ↔ τ = σ

lemma substRel_apply_substBar {y : BarTree E} (hy : Valid y) {p : List Bool} {s : Bool}
    (h : IsUncut y p s) (r : Mono E 3 → K) (σ : Mono E 3) :
    substRel K y p s r (substBar y p s σ.1) = r σ

theorem winCoef_mem_of_mem_J {R : Submodule K (Mono E 3 → K)} {n : ℕ} {z : BarTree E →₀ K}
    (hzJ : z ∈ J K R) (hz : z ∈ C K n (n - 2)) {y : BarTree E} (hy : Adm n (n - 2) y)
    {p : List Bool} {s : Bool} (h : IsUncut y p s) : winCoef K y p s z ∈ R

theorem mem_J_iff_winCoef {R : Submodule K (Mono E 3 → K)} {n : ℕ} {z : BarTree E →₀ K}
    (hz : z ∈ C K n (n - 2)) :
    z ∈ J K R ↔ ∀ y p s, Adm n (n - 2) y → IsUncut y p s → winCoef K y p s z ∈ R

lemma disjoint_lset_of_nodup_bind {s : Multiset ℕ} {xs : ℕ → STree E}
    (h : (s.bind fun a => (xs a).labels).Nodup) {a b : ℕ} (ha : a ∈ s) (hb : b ∈ s)
    (hab : a ≠ b) : Disjoint (lset (xs a)) (lset (xs b))

lemma atFirst_first {A : Finset ℕ} {xs : ℕ → STree E}
    (hm : Set.InjOn (fun a => (xs a).first) ↑A) {a : ℕ} (ha : a ∈ A) :
    atFirst A xs (xs a).first = xs a

theorem Rules.isFull_of_mem_KD {A : Finset ℕ} {w : ℕ} {v : SMono (BE E) A →₀ K}
    (hv : v ∈ G.KD A w) {X : SMono (BE E) A} (hX : X ∈ v.support)
    (hmax : ∀ Y ∈ v.support, ¬ O.lt (forgetM X) (forgetM Y)) : G.IsFull (forgetM X)

theorem Rules.exists_kappa {A : Finset ℕ} {w : ℕ} (hw : 0 < w) {t : SMono E A}
    (ht : t.1.weight = w) (hfull : G.IsFull t) :
    ∃ κ ∈ G.KD A w, κ - Finsupp.single (cutAllM t) 1 ∈
      Finsupp.supported K K {Y | O.lt (forgetM Y) t}

lemma Rules.kappa_sub (t : G.Full A w) :
    G.kappa hquad hom hres hw t - Finsupp.single (cutAllM t.1) 1 ∈
      Finsupp.supported K K {Y | O.lt (forgetM Y) (forgetM (cutAllM t.1))}

theorem finsupp_ext {f g : MultilinearMap R (fun _ : ι => X →₀ R) W}
    (h : ∀ t : ι → X, f (fun i => Finsupp.single (t i) 1) = g (fun i => Finsupp.single (t i) 1)) :
    f = g

theorem quot_ext' {f g : MultilinearMap R (fun i => M i ⧸ N i) W}
    (h : ∀ x : ∀ i, M i, f (fun i => (N i).mkQ (x i)) = g (fun i => (N i).mkQ (x i))) :
    f = g

private lemma dias_lr (h : DiasRel 3 (DiasGen.lc p q) (DiasGen.rc p' q')) :
    leftComb (NSPres.gen (ρ := DiasRel) (DiasGen.op p)) (NSPres.gen (DiasGen.op q))
      = rightComb (NSPres.gen (DiasGen.op p')) (NSPres.gen (DiasGen.op q'))

lemma val_mk_comp (a b : ℕ) {n : ℕ} (x : PTrias (a + 1 + b)) (y : PTrias n) (k : ℕ) :
    val ⟨a + n + b, NSSetOperad.comp a b x y⟩ k =
      if k < a then val ⟨_, x⟩ k
      else if k < a + n then val ⟨_, x⟩ a && val ⟨n, y⟩ (k - a)
      else val ⟨_, x⟩ (k - n + 1)

lemma val_comp (X : Arr PTrias) {a : ℕ} (ha : a < X.1) (Y : Arr PTrias) (k : ℕ) :
    val (comp X a Y) k =
      if k < a then val X k
      else if k < a + Y.1 then val X a && val Y (k - a)
      else val X (k - Y.1 + 1)

lemma val_bin (g : PTrias 2) (X Y : Arr PTrias) (k : ℕ) :
    val (bin g X Y) k =
      if k < X.1 then val ⟨2, g⟩ 0 && val X k else val ⟨2, g⟩ 1 && val Y (k - X.1)

private lemma trias_lr (h : TriasRel 3 (TriasGen.lc p q) (TriasGen.rc p' q')) :
    leftComb (NSPres.gen (ρ := TriasRel) (TriasGen.op p)) (NSPres.gen (TriasGen.op q))
      = rightComb (NSPres.gen (TriasGen.op p')) (NSPres.gen (TriasGen.op q'))

private lemma pt_eq {X Y : Arr PTrias} (hX : X.1 = 3) (hY : Y.1 = 3)
    (h0 : PTrias.val X 0 = PTrias.val Y 0) (h1 : PTrias.val X 1 = PTrias.val Y 1)
    (h2 : PTrias.val X 2 = PTrias.val Y 2) : X = Y

