lemma comp_slot {A B : Type} [Fintype A] [DecidableEq A] [Fintype B] [DecidableEq B] {j j' : A}
    (h : j = j') (x : Q A) (y : Q B) :
    comp (R := R) j' x y = map (R := R) (slotEquiv (B := B) h) (comp (R := R) j x y)

