theorem mcL_compL_outer {Y Y₁ Y₂ Y₃ Y₁₂ Y₂₃ : Finset ℕ} {m m' : ℕ}
    (s₁ : LabSplit Y₂₃ Y₂ Y₃ m') (s₂ : LabSplit Y Y₁ Y₂₃ m) (s₃ : LabSplit Y₁₂ Y₁ Y₂ m)
    (s₄ : LabSplit Y Y₁₂ Y₃ m') (X : 𝒞 (Lab Y₁)) {W : 𝒞 (Lab Y₂)}
    (hW : FreeGrL.unitCoeffL R (BarGen I) _ W = 0) (V : 𝒞 (Lab Y₃)) :
