lemma respects_symRel_iff {S : (A : Type) → [Fintype A] → [DecidableEq A] → Type v}
    [SetOperad S] (ρ : ∀ n : ℕ, NSSyn T n → NSSyn T n → Prop) (f : ∀ n, T n → S (Fin n)) :
