    (hl : l.Nodup) (v : Stage B l → V) :
    α.act (SymOperad.fill R p q l hl) v = α.act p fun a =>
      if h : a ∈ l then α.act (q a) (fun b => v (Sum.inr ⟨⟨a, h⟩, b⟩))
